/* Lightweight Markdown renderer — handles headings, bold, italic, lists, blockquotes, code, hr, paragraphs */
var marked = (function () {
  function escape(s) {
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }
  function inlineHtml(s) {
    return s
      .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.+?)\*/g, '<em>$1</em>')
      .replace(/`([^`]+)`/g, '<code>$1</code>');
  }
  function parse(md) {
    var lines = md.split(/\r?\n/);
    var out = '';
    var i = 0;
    while (i < lines.length) {
      var line = lines[i];

      // Blank line
      if (/^\s*$/.test(line)) { i++; continue; }

      // Heading
      var hm = line.match(/^(#{1,6})\s+(.*)/);
      if (hm) {
        var level = hm[1].length;
        out += '<h' + level + '>' + inlineHtml(escape(hm[2])) + '</h' + level + '>\n';
        i++; continue;
      }

      // HR
      if (/^[-*_]{3,}\s*$/.test(line)) {
        out += '<hr>\n'; i++; continue;
      }

      // Blockquote
      if (/^>/.test(line)) {
        var bq = '';
        while (i < lines.length && /^>/.test(lines[i])) {
          bq += lines[i].replace(/^>\s?/, '') + '\n';
          i++;
        }
        out += '<blockquote>' + parse(bq) + '</blockquote>\n';
        continue;
      }

      // Unordered list
      if (/^[-*+]\s/.test(line)) {
        out += '<ul>\n';
        while (i < lines.length && /^[-*+]\s/.test(lines[i])) {
          out += '<li>' + inlineHtml(escape(lines[i].replace(/^[-*+]\s+/, ''))) + '</li>\n';
          i++;
        }
        out += '</ul>\n';
        continue;
      }

      // Ordered list
      if (/^\d+\.\s/.test(line)) {
        out += '<ol>\n';
        while (i < lines.length && /^\d+\.\s/.test(lines[i])) {
          out += '<li>' + inlineHtml(escape(lines[i].replace(/^\d+\.\s+/, ''))) + '</li>\n';
          i++;
        }
        out += '</ol>\n';
        continue;
      }

      // Fenced code block
      if (/^```/.test(line)) {
        i++;
        var code = '';
        while (i < lines.length && !/^```/.test(lines[i])) {
          code += escape(lines[i]) + '\n';
          i++;
        }
        i++; // skip closing ```
        out += '<pre><code>' + code + '</code></pre>\n';
        continue;
      }

      // Paragraph
      var para = '';
      while (i < lines.length && !/^\s*$/.test(lines[i])
             && !/^#{1,6}\s/.test(lines[i])
             && !/^[-*+]\s/.test(lines[i])
             && !/^\d+\.\s/.test(lines[i])
             && !/^>/.test(lines[i])
             && !/^```/.test(lines[i])
             && !/^[-*_]{3,}\s*$/.test(lines[i])) {
        para += (para ? ' ' : '') + lines[i];
        i++;
      }
      out += '<p>' + inlineHtml(escape(para)) + '</p>\n';
    }
    return out;
  }
  return { parse: parse };
})();
